def trusted(path):
    p=Path(path)
    for part in (p,*p.parents):
        st=part.lstat()
        if stat.S_ISLNK(st.st_mode) or st.st_uid!=0 or st.st_mode&0o022:raise SystemExit('Stopped: installed runtime or parent is not root-owned and protected.')

